INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "雷邺", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：雷邺。", "biography": null, "status": "draft", "id": "f68d07b7-55a1-5458-938c-ee407fab48cb"}, {"name": "乐彦祯", "aliases": ["乐行达"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的乐彦祯：获赐名者。", "biography": null, "status": "draft", "id": "bc42c29a-a3a4-51c5-ad15-16bf1105e036"}, {"name": "乐从训", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：乐从训。", "biography": null, "status": "draft", "id": "29c299a6-ecba-57a3-bc64-afce0b5389cd"}, {"name": "李罕之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：李罕之。", "biography": null, "status": "draft", "id": "3a3944bf-1d15-5b41-8fde-e3f51fbe285c"}, {"name": "张全义", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受封者。", "biography": null, "status": "draft", "id": "3d89e670-5812-57eb-a061-8aaea77bd5e8"}, {"name": "王友遇", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：王友遇。", "biography": null, "status": "draft", "id": "5639a56d-42f4-5118-a5b3-6ddef15e3f0b"}, {"name": "王重盈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王重盈。", "biography": null, "status": "draft", "id": "04d3efcf-c998-55c8-b602-766123712a88"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "唐僖宗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：唐僖宗。", "biography": null, "status": "draft", "id": "5ebe384f-47ad-563f-8232-7ce601cf3c88"}, {"name": "李保", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李保。", "biography": null, "status": "draft", "id": "bb184008-82d4-5e86-ac1e-7c99033987ec"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "刘季述", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：刘季述。", "biography": null, "status": "draft", "id": "c273a382-8a3f-57cd-beb9-1e7c82dede3a"}, {"name": "韦昭度", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：韦昭度。", "biography": null, "status": "draft", "id": "4d186310-6106-56bc-9a34-fa1d5d5d7894"}, {"name": "李唐宾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的李唐宾：归降者。", "biography": null, "status": "draft", "id": "7fd6597f-12ac-5146-92eb-9aea9b8b7427"}, {"name": "朱珍", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的朱珍，在此段中为击退者。", "biography": null, "status": "draft", "id": "863c86d4-bcc1-57f7-a877-4c9d05eed8ca"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条