INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱全忠遣雷邺至魏籴粮，雷邺被杀", "start_year": 888, "end_year": 888, "time_original": "乐彦祯被逐前后；具体日未载", "dynasty": "唐", "description": "朱全忠拟讨蔡州，先遣雷邺携银赴魏州买粮；魏博牙兵逐乐彦祯后，在馆舍杀雷邺。", "phases": [], "location_name": "魏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "98abf34a-c384-56bf-a1ec-42b0d7858130"}, {"title": "乐从训败后向朱全忠求援", "start_year": 888, "end_year": 888, "time_original": "乐从训退内黄后；具体日未载", "dynasty": "唐", "description": "乐从训遭魏州军击败后向朱全忠求援。", "phases": [], "location_name": "内黄、宣武", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e2e70899-a56d-58f7-954e-af09c3e59a84"}, {"title": "李罕之张全义昔日结盟", "start_year": null, "end_year": null, "time_original": "此前；具体年日未载", "dynasty": "唐", "description": "《通鉴》追叙李罕之与张全义曾刻臂为盟，起初相处友善。", "phases": [], "location_name": "河阳、河南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7d35bbfd-90e5-586c-8b27-ed0dc430f62f"}, {"title": "李罕之屡索张全义粮帛", "start_year": null, "end_year": null, "time_original": "昔日结盟后至888年前后；具体日期未载", "dynasty": "唐", "description": "李罕之屡向张全义索粮帛，不足时拘河南官吏至河阳杖责；张全义尽力供给，河南将佐不满。", "phases": [], "location_name": "河阳、河南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e0420048-2f65-56a8-b370-e585ba4ce7fc"}, {"title": "李罕之攻绛州晋州", "start_year": 888, "end_year": 888, "time_original": "888年二月至三月前后；具体日未载", "dynasty": "唐", "description": "李罕之率军攻绛州，刺史王友遇投降；继而进攻晋州。", "phases": [], "location_name": "绛州、晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7ffc67cc-dd7f-54dc-8f9f-70393389b147"}, {"title": "张全义趁李罕之攻晋州取河阳", "start_year": 888, "end_year": 888, "time_original": "李罕之攻晋州时；具体日未载", "dynasty": "唐", "description": "王重盈秘密与张全义谋划，张全义趁李罕之出兵晋州夜袭河阳，黎明进入三城并俘其家属；李罕之逃泽州，向李克用求援。", "phases": [], "location_name": "河阳、泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "90d1d0a6-8581-5dfa-90ca-64087a10946f"}, {"title": "三月戊戌日食", "start_year": 888, "end_year": 888, "time_original": "888年三月戊戌朔", "dynasty": "唐", "description": "《通鉴》记三月朔日发生日全食。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0d8f5c3a-3977-5ec0-9424-1f34a44dd825"}, {"title": "唐僖宗病重", "start_year": 888, "end_year": 888, "time_original": "888年三月己亥至壬寅", "dynasty": "唐", "description": "唐僖宗己亥病复作，壬寅病危。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "923cff0d-7916-5bac-952d-9248448ed0b3"}, {"title": "寿王李杰立为皇太弟监军国", "start_year": 888, "end_year": 888, "time_original": "888年三月壬寅", "dynasty": "唐", "description": "群臣曾寄望吉王保；杨复恭请立寿王杰。朝廷下诏立寿王杰为皇太弟、监军国事，刘季述遣兵迎入少阳院。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "52808df7-dd5c-5244-9dfc-09b79acb799f"}, {"title": "唐僖宗崩于灵符殿", "start_year": 888, "end_year": 888, "time_original": "888年三月癸卯", "dynasty": "唐", "description": "唐僖宗在灵符殿去世；遗制令皇太弟李杰改名李敏，以韦昭度摄冢宰。", "phases": [], "location_name": "长安灵符殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cbaeb949-fdcc-53b9-8319-ea153f39e3d5"}, {"title": "唐昭宗即位", "start_year": 888, "end_year": 888, "time_original": "唐僖宗崩后；具体日未载", "dynasty": "唐", "description": "寿王李杰即位为唐昭宗。《通鉴》记其即位初尊礼大臣，试图振兴朝廷。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2efc0634-92e3-5db6-a25f-9fd712110741"}, {"title": "朱全忠分兵攻蔡救乐从训", "start_year": 888, "end_year": 888, "time_original": "888年三月前后；具体日未载", "dynasty": "唐", "description": "朱全忠在宋州拟讨秦宗权，乐从训求援后移屯滑州，遣李唐宾等攻蔡州，又遣朱珍等救乐从训。", "phases": [], "location_name": "宋州、滑州、蔡州方向、魏博方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "993d5019-9e23-5e58-a7b5-f2e20fe47097"}, {"title": "朱珍军入魏博取三镇", "start_year": 888, "end_year": 888, "time_original": "分兵救乐从训后；具体日未载", "dynasty": "唐", "description": "朱珍等军渡白马，取黎阳、临河、李固三镇，至内黄击败魏博军，俘周儒等将领。", "phases": [], "location_name": "白马、黎阳、临河、李固、内黄", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9003c2ad-0842-5877-89e2-1372470e6e19"}, {"title": "李克用遣康君立等助李罕之攻河阳", "start_year": 888, "end_year": 888, "time_original": "888年三月至四月前后；具体日未载", "dynasty": "唐", "description": "李克用任康君立为南面招讨使，令其督李存孝、薛阿檀、史俨、安全俊、安休休率骑兵援李罕之，攻河阳。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e12bca49-5679-506a-bc41-85b30c943476"}, {"title": "张全义守河阳向朱全忠求援", "start_year": 888, "end_year": 888, "time_original": "李克用援军攻河阳时；具体日未载", "dynasty": "唐", "description": "张全义守河阳，城中粮尽，向朱全忠求援，以妻子为质。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cde68809-6970-52e3-8054-962ca7312b98"}, {"title": "王建攻彭州后劫掠西川", "start_year": 888, "end_year": 888, "time_original": "888年四月庚午前；具体日未载", "dynasty": "唐", "description": "王建攻彭州，陈敬瑄率军救援后王建退去；《通鉴》又记王建军大掠西川，十二州受害。", "phases": [], "location_name": "彭州、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "570a6941-7a8a-58c2-8bb5-a02242b3fd86"}, {"title": "朝廷追尊昭宗母王氏", "start_year": 888, "end_year": 888, "time_original": "888年四月庚午", "dynasty": "唐", "description": "朝廷追尊新帝之母王氏为恭宪皇后。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fb0bec52-24e5-5d3b-a8e0-d5faf2ba5417"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

